/* QuickSight e4f7a0d3-6b72-47ce-a05c-e0745e7eea32 */
SELECT "title", "link", "description", CAST(PARSE_DATETIME("date", 'YYYY-MM-dd''T''HH:mm:ss''Z''') AS TIMESTAMP) AS "date", "creator", "category", "year", "month", "day"
