/* cppi::0b20a539382e32195a577df2d556c500b60c145ea90204e95962c8b994a15fd2 */
select business_date as date_, security_id, 'EUGBR' as strategy_id, weight_ndo as weight
                                  from (select * from (select *, ROW_NUMBER() OVER (PARTITION by business_date, id_vendor_security_ndo, id_cppib_index order by feed_version asc) as rn from market.cppib_market_index_constituents_mapped_rimes) where rn = 1)
                                  where business_date >= date '2025-06-17' and business_date <= date '2025-06-17' and weight_ndo>0 and id_cppib_index = 'EUGBR_GR_USD_0_0' and security_id is not null

/* cppi::d3b760b51900aac235b502f30a8dc5803609e448c09678edff597a3e6993f141 */
SELECT * FROM ci_etl_db_dev.ci_capital_pipeline_sentry_holdings_transformed
                WHERE CAST(extract_timestamp AS TIMESTAMP) = TIMESTAMP '2025-06-18 16:36:22'

/* cppi::be8fe7830b309c95fd6fab9e394ba36637b94885863c2eba9730642a0a1d09f8 */
select business_date as date_, security_id, 'SP500_35' as strategy_id, weight_ndo as weight
                                  from (select * from (select *, ROW_NUMBER() OVER (PARTITION by business_date, id_vendor_security_ndo, id_cppib_index order by feed_version asc) as rn from market.cppib_market_index_constituents_mapped_rimes) where rn = 1)
                                  where business_date >= date '2025-06-13' and business_date <= date '2025-06-17' and weight_ndo>0 and id_cppib_index = 'SP500_35_GR_USD_0_0' and security_id is not null

/* cppi::eceb8685ebc4d4f8b3b34f327842569d7a336c57a1b08eb1f9203e42399d6dba */
select index_id, time_key, currency_code, geography, country_name, index_value, source_file
from (
        select *, max(last_publish) over (partition by index_id, time_key) max_publish
            from market.tfm_gdp_index
            where time_key between 1984 and 2030
            and last_publish <= date '2025-01-02'
    ) a
where last_publish = max_publish

